+        band: 'p0_consumable_baseline',
+        scheduler_behavior: 'accounted_monitor_only_not_in_remaining_production_queue',
+      },
+      {
+        band: 'p1_evidence_complete_text_procedure',
+        scheduler_behavior: 'go_first_when_review_load_budget_is_within_threshold',
+      },
+      {
+        band: 'p2_review_load_managed',
+        scheduler_behavior: 'schedule_after_p1_and_defer_if_review_load_budget_is_exceeded',
+      },
+      {
+        band: 'p3_visual_evidence_gap_deferred',
+        scheduler_behavior: 'schedule_with_visual-evidence stop/go gate before semantic production',
